  "and": "y", "{0} mph, gusts {1} mph": "{0} mph, ráfagas de {1} mph", "updated {0} p.m.": "actualizado {0} p.m.", "updated {0} a.m.": "actualizado {0} a.m.",
  "NOAA gauge": "medidor de NOAA", "Light rain over you": "Lluvia ligera sobre usted", "Moderate rain over you": "Lluvia moderada sobre usted",
